/*============================================================
  load_sample_data.sql — Load sample data into demo tables
  
  Run this after 00_setup.sql to populate tables with realistic
  sample data for the demo.
============================================================*/

USE DATABASE CORTEX_AI_DEMO;
USE WAREHOUSE CORTEX_AI_DEMO_WH;

/*------------------------------------------------------------
  Search Schema — Product catalog, reviews, hair profiles
------------------------------------------------------------*/
USE SCHEMA SEARCH;




/*------------------------------------------------------------
  Sentiment Schema — Multi-channel review data
------------------------------------------------------------*/
USE SCHEMA SENTIMENT;


SELECT 'Sample data loaded successfully!' AS STATUS;
SELECT 'SEARCH: ' || (SELECT COUNT(*) FROM SEARCH.PRODUCT_CATALOG) || ' products, ' || (SELECT COUNT(*) FROM SEARCH.PRODUCT_REVIEWS) || ' reviews, ' || (SELECT COUNT(*) FROM SEARCH.HAIR_PROFILES) || ' profiles' AS SEARCH_DATA;
SELECT 'SENTIMENT: ' || (SELECT COUNT(*) FROM SENTIMENT.RAW_REVIEWS) || ' reviews' AS SENTIMENT_DATA;
