INSERT INTO PRODUCT_CATALOG VALUES
('HC-001', 'Premium Hair Color Kit', 'Permanent Color', 'Golden Brown', '5.5NNG', 'Golden Brown 5.5NNG is a light golden brown shade that delivers rich, multidimensional color with 100% gray coverage. Our gentle formula is free of ammonia, parabens, and resorcinol. Enriched with keratin and argan oil for healthier-looking hair. Includes color activator, barrier cream, cap, gloves, and detailed instructions.', 'Aqua, Ethanolamine, PEG-2 Oleamine, Oleic Acid, Keratin, Argan Oil, Ginseng Root Extract, No Ammonia', 'Full Coverage', 'All hair types', 26.50, 'DTC, Ulta, Target, Sally Beauty, Amazon', '2026-01-15'),
('HC-002', 'Premium Hair Color Kit', 'Permanent Color', 'Dark Blonde', '6N', 'Dark Blonde 6N is a dark blonde shade perfect for natural-looking coverage. The same gentle ammonia-free formula with keratin and argan oil for healthier-looking hair after coloring. Suitable for first-time colorists and experienced users alike.', 'Aqua, Ethanolamine, PEG-2 Oleamine, Oleic Acid, Keratin, Argan Oil, Ginseng Root Extract, No Ammonia', 'Full Coverage', 'All hair types', 26.50, 'DTC, Ulta, Target, Sally Beauty, Amazon', '2026-01-15'),
('HC-003', 'Premium Hair Color Kit', 'Permanent Color', 'Light Auburn', '7.5NGA', 'Light Auburn 7.5NGA is a golden light auburn shade with warm copper undertones. Ideal for redheads or those wanting to add warm dimension. Proprietary color technology ensures fade-resistant results that last 6-8 weeks.', 'Aqua, Ethanolamine, PEG-2 Oleamine, Oleic Acid, Keratin, Argan Oil, Ginseng Root Extract, No Ammonia', 'Full Coverage', 'All hair types', 26.50, 'DTC, Ulta, Target, Amazon', '2026-02-01'),
('HC-004', 'Root Touch Up', 'Root Coverage', 'Medium Brown', '6NNA', 'Quick 10-minute root touch up powder for between-color maintenance. Blends seamlessly with permanent color. Water and sweat resistant. Compact mirror included for easy application.', 'Mica, Silica, Calcium Aluminum Borosilicate, Isopropyl Myristate', 'Roots Only', 'All hair types', 32.00, 'DTC, Ulta, Sally Beauty, Amazon', '2026-01-20'),
('HC-005', 'Color Therapy Hair Mask', 'Hair Care', 'Universal', NULL, 'Deep conditioning color-depositing hair mask that refreshes color while nourishing hair. Contains argan oil, keratin, and rice protein. Use weekly to extend time between colorings and restore shine and softness.', 'Aqua, Cetearyl Alcohol, Behentrimonium Chloride, Argan Oil, Keratin, Rice Protein, Panthenol', NULL, 'Color-treated hair', 28.00, 'DTC, Ulta, Target, Sally Beauty', '2026-02-10'),
('HC-006', 'Premium Hair Color Kit', 'Permanent Color', 'Dark Brown', '3N', 'Dark Brown 3N delivers salon-quality results at home. Rich, deep brunette color with warm undertones and complete gray coverage. Our gentle ammonia-free formula leaves hair feeling silky and healthy.', 'Aqua, Ethanolamine, PEG-2 Oleamine, Oleic Acid, Keratin, Argan Oil, Ginseng Root Extract, No Ammonia', 'Full Coverage', 'All hair types', 26.50, 'DTC, Ulta, Target, Sally Beauty, Amazon, Walmart', '2026-01-15'),
('HC-007', 'Premium Hair Color Kit', 'Permanent Color', 'Medium Brown', '5N', 'Medium Brown 5N is perfect for those wanting natural-looking brunette color. Excellent gray coverage with a neutral base that avoids brassiness. Formulated with a proprietary gentle, ammonia-free blend.', 'Aqua, Ethanolamine, PEG-2 Oleamine, Oleic Acid, Keratin, Argan Oil, Ginseng Root Extract, No Ammonia', 'Full Coverage', 'All hair types', 26.50, 'DTC, Ulta, Target, Sally Beauty, Amazon', '2026-02-01'),
('HC-008', 'Color Reviving Gloss', 'Gloss Treatment', 'Espresso', '3.5N', 'In-shower color gloss that refreshes and boosts shine between color sessions. Non-damaging, ammonia-free formula adds depth and dimension. Lasts up to 3 washes. Available in shades matched to the permanent color line.', 'Aqua, Ceteareth-20, Stearamidopropyl Dimethylamine, Keratin, Argan Oil', NULL, 'Color-treated hair', 15.00, 'DTC, Ulta, Amazon', '2026-03-01');
INSERT INTO PRODUCT_REVIEWS VALUES
('r001', 'HC-001', 'c001', '2026-03-10', 5, 'Best gray coverage ever!', 'I have been using Golden Brown for over 3 years and it is the only hair color that completely covers my gray. The color is rich and multidimensional, not flat at all. My hair actually feels better after coloring than before. Will never go back to salon coloring for this.', 'DTC', TRUE, 'Straight', 'Golden Brown'),
('r002', 'HC-001', 'c008', '2026-03-05', 4, 'Great color, tricky application', 'Love the Golden Brown shade but I find the application process a bit messy. The color itself is gorgeous and covers my grays perfectly. Wish the applicator bottle was easier to use. Color lasts about 6 weeks for me.', 'Ulta', TRUE, 'Straight', 'Golden Brown'),
('r003', 'HC-006', 'c006', '2026-03-15', 5, 'Salon quality at home', 'Dark Brown gives me the exact same results as my $300 salon visits. The color is rich and dimensional, and my hair feels incredibly soft afterward. The keratin and argan oil make such a difference. My colorist was shocked when I told her I colored at home.', 'DTC', TRUE, 'Fine', 'Dark Brown'),
('r004', 'HC-003', 'c003', '2026-02-28', 3, 'Color faded faster than expected', 'The Light Auburn shade was beautiful when first applied — loved the auburn tones. But by week 3, the red had faded significantly and looked more brown than auburn. I expected at least 6 weeks of vibrant color. The application process was easy though.', 'SALON', TRUE, 'Curly', 'Light Auburn'),
('r005', 'HC-007', 'c012', '2026-03-18', 5, 'Perfect natural brown', 'Medium Brown is exactly the shade I have been looking for. No brassiness, no orange tones — just a beautiful, natural brown. The gray coverage is complete. I switched from a box store brand and the quality difference is night and day.', 'DTC', TRUE, 'Wavy', 'Medium Brown'),
('r006', 'HC-002', 'c002', '2026-03-12', 4, 'Nice blonde for gray', 'Dark Blonde gives good coverage on my grays while keeping the color natural looking. The shade works well with my complexion. Only giving 4 stars because the smell during application is still pretty strong despite being ammonia-free.', 'DTC', TRUE, 'Wavy', 'Dark Blonde'),
('r007', 'HC-004', 'c004', '2026-02-15', 2, 'Disappointed with root touch up', 'The root touch up powder does not match the Medium Brown shade at all. It looks orangey compared to the permanent color. Also, it transfers onto my pillow despite claiming to be water resistant. Expected much better for $32.', 'Amazon', TRUE, 'Straight', 'Medium Brown'),
('r008', 'HC-005', NULL, '2026-03-20', 5, 'Color therapy is amazing', 'This hair mask is a game changer. It keeps my color looking fresh between colorings and my hair feels like silk. I use it once a week and it extends my color by at least 2 weeks. Worth every penny.', 'Target', FALSE, 'Thick', NULL),
('r009', 'HC-006', 'c013', '2026-03-08', 5, 'Salon experience was incredible', 'Got my Dark Brown color done at the Bethesda salon and the experience was outstanding. My colorist Emily really understood what I wanted. The salon is beautiful and the results speak for themselves. Already booked my next appointment.', 'SALON', TRUE, 'Straight', 'Dark Brown'),
('r010', 'HC-001', 'c010', '2026-03-22', 5, 'Loyal customer for 8 years', 'I discovered this brand in 2018 and have never looked back. Golden Brown covers my 50% gray perfectly and the subscription ensures I never run out. The quality has actually improved over the years. Best hair color on the market, period.', 'DTC', TRUE, 'Thick', 'Golden Brown');
